<script setup lang="ts">
import { ref,watch } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { useI18n } from 'vue-i18n';import { api } from '@/api';import { useMerchantStore } from '@/stores/merchant';import { money } from '@shared/utils/money';import { datetime } from '@shared/utils/datetime';import type { SvRecord } from '@/api/stored-value-types';
const {t}=useI18n();const merchant=useMerchantStore();const record=ref<SvRecord|null>(null);const failed=ref(false);const error=ref('');let no='',store='',seq=0;
async function load(){const token=++seq;try{if(!store){await merchant.ensureStores();store=merchant.storeNo;}const r=await api.mSvRecord(no,store);if(token===seq&&store===merchant.storeNo){record.value=r;failed.value=false;}}catch(e){if(token===seq){failed.value=true;error.value=(e as Error).message;}}}
watch(()=>merchant.storeNo,()=>{seq++;record.value=null;failed.value=true;error.value=t('storedValue.leaveStore');});onLoad(q=>{no=q?.recordNo||'';void load();});
</script>
<template><sh-scaffold :title-suffix="merchant.multiStore ? merchant.currentStore?.name : ''" title-key="storedValue.recordDetail" :denied="!merchant.can('pay:sv:account:read')" :failed="failed" :pending="!record&&!failed" @retry="load">
 <view v-if="record" class="sh-card sv-card"><text class="txt-title">{{t(record.type==='RECHARGE'?'storedValue.recharge':'storedValue.redemption')}}</text><text class="txt-price sh-num">{{record.signedAmountMinor>0?'+':''}}{{money(record.signedAmountMinor,record.currency)}}</text><text class="txt-body">{{record.title}}</text></view>
 <view v-if="record" class="sh-card sv-card"><sh-kv :label="t('storedValue.customers')" between>{{record.maskedName}}</sh-kv><sh-kv :label="t('storedValue.store')" between>{{record.storeName}}</sh-kv><sh-kv :label="t('storedValue.occurredAt')" between>{{datetime(Date.parse(record.occurredAt))}}</sh-kv><sh-kv v-if="record.documentNo" :label="t('storedValue.businessNo')" between><text class="sh-num">{{record.documentNo}}</text></sh-kv><sh-kv :label="t('storedValue.afterBalance')" between>{{money(record.balanceAfterMinor,record.currency)}}</sh-kv></view>
 <view v-if="record?.type==='RECHARGE'" class="sh-card sv-card"><sh-kv :label="t('storedValue.paid')" between>{{money(record.paidAmountMinor||0,record.currency)}}</sh-kv><sh-kv :label="t('storedValue.bonus')" between>{{money(record.bonusAmountMinor||0,record.currency)}}</sh-kv></view><text v-if="error" class="sh-hint">{{error}}</text>
</sh-scaffold></template>
